/* 赛段排名制晋级配置展示。 */
(function(){
  const previousRender=window.renderSuper;
  function stagesRanking(){const stages=[['报名阶段','2026-06-01 至 06-07','资格确认','—','—','报名用户进入初赛','已结束'],['初赛阶段','2026-06-01 至 06-30','按排名晋级','个人积分榜','前 50 名','生成复赛候选名单','进行中'],['复赛阶段','2026-07-01 至 07-31','按排名晋级','个人积分榜','前 20 名','生成决赛候选名单','待开始'],['决赛阶段','2026-08-10 至 08-20','个人积分榜','个人积分榜','—','生成最终获奖名单','待开始']];return `<div class="page-heading"><div><h1>赛段管理</h1><p>赛段结束后按个人积分排名自动生成下一赛段候选名单</p></div><div class="toolbar"><button class="btn-primary" onclick="showToast('已打开新建赛段配置（Mock）')">新建赛段</button></div></div><section class="panel"><div class="panel-title"><span>2026 年岗位技能竞赛 · 赛段流程</span><a>排名制晋级</a></div><div class="stage-flow">${stages.map((x,i)=>`<article class="stage-flow-card ${i===1?'active':''}"><div class="stage-number"><span>赛段 0${i+1}</span><span class="status ${i===1?'green':'gray'}">${x[6]}</span></div><h3>${x[0]}</h3><p>赛段时间：${x[1]}<br/>晋级方式：${x[2]}<br/>${x[3]==='—'?'':`排名口径：${x[3]}<br/>晋级人数：${x[4]}<br/>`}结束后：${x[5]}</p><div class="stage-foot"><a class="text-link" onclick="showToast('赛段操作已执行（Mock）')">${i===1?'结束赛段':i===0?'已发布':'发布赛段'}</a><a class="text-link" onclick="showToast('打开排名制规则配置')">配置规则</a><a class="text-link">查看数据</a></div></article>${i<3?'<div class="stage-flow-arrow"><span>➜</span></div>':''}`).join('')}</div></section><div class="data-table-wrap" style="margin-top:14px"><table class="data-table"><thead><tr><th>赛段名称</th><th>赛段时间</th><th>晋级方式</th><th>排名口径</th><th>晋级人数</th><th>结束后动作</th><th>状态</th></tr></thead><tbody>${stages.map(x=>`<tr>${x.map((v,i)=>`<td>${i===6?`<span class="status ${v==='进行中'?'green':'gray'}">${v}</span>`:v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="p1-box">高级赛制编排（P1）：支持拖拽节点、连线、分支、合并和条件跳转。</div>`}
  window.renderSuper=function(page){if(page!=='stages')return previousRender(page);const content=document.getElementById('superContent');content.innerHTML=stagesRanking();document.getElementById('crumb').textContent='赛段管理';bindControls()};
})();
